import type { Persistence } from "./database/persistence";
// Env is generated by `wrangler types`; secrets remain optional until configured.
export type RuntimeEnv = {
  [K in Exclude<keyof Env, "DB" | "ASSETS">]: Env[K] extends string
    ? string
    : Env[K];
} & {
  DB: Persistence;
  ASSETS?: Env["ASSETS"];
  BETTER_AUTH_SECRET?: string;
  RESEND_API_KEY?: string;
  EMAIL?: SendEmail;
  MAIL_FROM?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  TURNSTILE_SITE_KEY?: string;
  TURNSTILE_SECRET_KEY?: string;
};
export type Actor = {
  id: string;
  email: string;
  name: string;
  status: string;
  roleId: string | null;
  twoFactorEnabled: boolean;
  mfaEpoch: number;
  sessionId: string;
  sessionCreatedAt: number;
  permissions: string[];
  isAdmin: boolean;
};
